// EOWRECOMP_VK_CACHE_STATS: feedback for guest pipeline creation, grouped by kind per renderer stats interval.
enum { PIPE_GRAPHICS, PIPE_COMPUTE, PIPE_KINDS };
typedef struct {
    uint64_t calls, worker, failed, valid, app_hits, total_ns, max_ns;
} PipelineFeedbackStats;
static PipelineFeedbackStats pipeline_feedback[PIPE_KINDS];
static pthread_mutex_t pipeline_feedback_lock = PTHREAD_MUTEX_INITIALIZER;
static bool pipeline_feedback_enabled;

static void record_pipeline_feedback(int kind, VkResult result, VkPipelineCreationFeedback feedback) {
    pthread_mutex_lock(&pipeline_feedback_lock);
    PipelineFeedbackStats *s = &pipeline_feedback[kind];
    s->calls++;
    s->worker += on_compile_worker;
    s->failed += result != VK_SUCCESS;
    if (result == VK_SUCCESS && (feedback.flags & VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT)) {
        s->valid++;
        s->app_hits += (feedback.flags & VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT) != 0;
        s->total_ns += feedback.duration;
        if (feedback.duration > s->max_ns) s->max_ns = feedback.duration;
    }
    pthread_mutex_unlock(&pipeline_feedback_lock);
}

static void report_pipeline_feedback(void) {
    PipelineFeedbackStats rows[PIPE_KINDS];
    pthread_mutex_lock(&pipeline_feedback_lock);
    memcpy(rows, pipeline_feedback, sizeof rows);
    memset(pipeline_feedback, 0, sizeof pipeline_feedback);
    pthread_mutex_unlock(&pipeline_feedback_lock);
    for (int i = 0; i < PIPE_KINDS; i++) {
        const PipelineFeedbackStats *s = &rows[i];
        if (!s->calls) continue;
        LOG("[vk-pipeline-feedback] %s calls %llu worker %llu inline %llu failed %llu valid %llu app_hits %llu "
            "driver_total %.3fms driver_max %.3fms\n", i == PIPE_GRAPHICS ? "graphics" : "compute",
            (unsigned long long)s->calls, (unsigned long long)s->worker, (unsigned long long)(s->calls - s->worker),
            (unsigned long long)s->failed, (unsigned long long)s->valid, (unsigned long long)s->app_hits,
            s->total_ns / 1e6, s->max_ns / 1e6);
    }
}

